public static String applyRelativePath(String path, String relativePath) {
    if (relativePath.startsWith("/")) {
        return relativePath; // Absolute path
    }
    String[] pathParts = path.split("/");
    String[] relativeParts = relativePath.split("/");
    int pathIndex = pathParts.length - 1;

    for (String part : relativeParts) {
        if (part.equals("..")) {
            if (pathIndex > 0) {
                pathIndex--; // Move up one directory
            }
        } else if (!part.equals(".")) {
            pathParts[++pathIndex] = part; // Add directory
        }
    }
    StringBuilder result = new StringBuilder();
    for (int i = 0; i <= pathIndex; i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(pathParts[i]);
    }
    return result.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    // Normalize the paths by removing any trailing slashes
    if (path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }
    if (relativePath.startsWith("/")) {
        relativePath = relativePath.substring(1);
    }

    // Split the paths into components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Process the relative path components
    int i = 0;
    while (i < relativePathComponents.length) {
        if (relativePathComponents[i].equals("..")) {
            // Move up one directory if possible
            if (pathComponents.length > 0) {
                pathComponents = Arrays.copyOf(pathComponents, pathComponents.length - 1);
            }
        } else if (!relativePathComponents[i].equals(".")) {
            // Add the component to the path
            String[] newPathComponents = new String[pathComponents.length + 1];
            System.arraycopy(pathComponents, 0, newPathComponents, 0, pathComponents.length);
            newPathComponents[pathComponents.length] = relativePathComponents[i];
            pathComponents = newPathComponents;
        }
        i++;
    }

    // Join the path components back into a single string
    return String.join("/", pathComponents);
}

public static String applyRelativePath(String path, String relativePath) {
    // Normalize the paths to remove any trailing slashes
    if (!path.isEmpty() && path.charAt(path.length() - 1) == '/') {
        path = path.substring(0, path.length() - 1);
    }
    if (!relativePath.isEmpty() && relativePath.charAt(0) == '/') {
        relativePath = relativePath.substring(1);
    }

    // Split the paths into components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Use a stack to build the resulting path
    Deque<String> resultStack = new ArrayDeque<>(Arrays.asList(pathComponents));

    for (String component : relativePathComponents) {
        if (component.equals("..")) {
            if (!resultStack.isEmpty()) {
                resultStack.pop(); // Move up one directory if possible
            }
        } else if (!component.equals(".")) {
            resultStack.push(component); // Add the component to the path
        }
    }

    // Build the final path from the stack
    StringBuilder resultPath = new StringBuilder();
    while (!resultStack.isEmpty()) {
        resultPath.insert(0, resultStack.removeLast());
        if (!resultStack.isEmpty()) {
            resultPath.insert(0, "/");
        }
    }

    return resultPath.toString();
}

