            if (!stack.isEmpty()) {
                stack.pop(); // Move up one directory
            }
        } else if (!component.equals(".")) {
            stack.push(component); // Add directory or file
        }
    }

    // Build the final path
    StringBuilder result = new StringBuilder();
    while (!stack.isEmpty()) {
        result.insert(0, stack.pollLast() + "/");
    }

    // Remove the trailing slash if the original path did not end with a slash
    String finalPath = result.toString();
    return finalPath.endsWith("/") && !path.endsWith("/") ? finalPath.substring(0, finalPath.length() - 1) : finalPath;
}

public static String applyRelativePath(String path, String relativePath) {
    // Normalize the paths by removing any trailing slashes
    if (path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }
    if (relativePath.startsWith("/")) {
        relativePath = relativePath.substring(1);
    }

    // Split the paths into components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Process each component of the relative path
    int i = 0;
    while (i < relativePathComponents.length) {
        String component = relativePathComponents[i];
        if (component.equals("..")) {
            // Move up one directory if possible
            if (pathComponents.length > 0) {
                pathComponents = Arrays.copyOf(pathComponents, pathComponents.length - 1);
            }
        } else if (!component.equals(".")) {
            // Add the component to the path
            String[] newPathComponents = Arrays.copyOf(pathComponents, pathComponents.length + 1);
            newPathComponents[pathComponents.length] = component;
            pathComponents = newPathComponents;
        }
        i++;
    }

    // Join the components back into a single string
    return String.join("/", pathComponents);
}

